example.code:
// In repository implementation
public class CustomerRepository(IMongoClientProvider clientProvider)
{
    private readonly IMongoCollection<CustomerDocument> _collection =
        clientProvider.GetCollection<CustomerDocument>("customers");
}

// In tests with mocking
var mockProvider = new Mock<IMongoClientProvider>();
mockProvider.Setup(p => p.GetCollection<CustomerDocument>("customers"))
    .Returns(mockCollection.Object);

// appsettings.json
{
  "MongoDB": {
    "ConnectionString": "mongodb+srv://user:pass@cluster.mongodb.net",
    "DatabaseName": "myservice-db",
    "ReadPreference": "primary"  // Override default for strong consistency
  }
}

// Registration in Program.cs
services.AddOptions<MongoSettings>()
    .BindConfiguration("MongoDB")
    .ValidateDataAnnotations()
    .ValidateOnStart();

public sealed class CustomerIndexProvider : IIndexDefinitionProvider<CustomerDocument>
{
    public IEnumerable<CreateIndexModel<CustomerDocument>> GetIndexes()
    {
        // Unique index on email
        yield return new CreateIndexModel<CustomerDocument>(
            Builders<CustomerDocument>.IndexKeys.Ascending(d => d.Email),
            new CreateIndexOptions { Name = "ix_customers_email", Unique = true });

        // Compound index for regional queries
        yield return new CreateIndexModel<CustomerDocument>(
            Builders<CustomerDocument>.IndexKeys
                .Ascending(d => d.Region)
                .Ascending(d => d.IsDeleted),
            new CreateIndexOptions { Name = "ix_customers_region" });
    }
}

